// Forward only verified and validated JK02 events to local MQTT publisher.
// The python publisher independently rejects unknown BMS addresses and
// validates electrical values. Never expose raw BLE passwords/serials.
if(String(env.get("BLE_MQTT_ENABLED")).toLowerCase()!=="true")return null;
const e=msg.payload||{},mac=String(e.address||"").toUpperCase();
if(!/^[A-F0-9]{2}(:[A-F0-9]{2}){5}$/.test(mac))return null;
let out=null,now=Date.now();
if(e.type===1||e.type===3||e.type===2){
 if(e.crc_ok!==true||typeof e.raw_hex!=="string"||!/^[0-9A-Fa-f]{600}$/.test(e.raw_hex))return null;
 const b=Buffer.from(e.raw_hex,"hex");
 if(b.length!==300||b.subarray(0,4).toString("hex")!=="55aaeb90"||b[4]!==e.type||
    b.subarray(0,299).reduce((s,x)=>(s+x)&255,0)!==b[299])return null;
 if(e.type===2){
  context.set("last_frame:"+mac,{
    sequence:e.sequence,at:now,raw_hex:e.raw_hex
  });
  return null; // Do not MQTT-publish *unvalidated* type-2 telemetry.
 }
 out={kind:"frame",address:mac,frame_type:e.type,raw_hex:e.raw_hex};
}else if(e.validation==="provisional_compare_with_BatMON"&&e.source_crc_ok===true){
 const cached=context.get("last_frame:"+mac)||{};
 const extras={};
 if(cached.sequence===e.sequence&&now-cached.at<=15000&&
    /^[0-9A-Fa-f]{600}$/.test(cached.raw_hex||"")){
  const b=Buffer.from(cached.raw_hex,"hex");
  if(e.format==="JK02_32S"){
    const u32=p=>b.readUInt32LE(p),i16=p=>b.readInt16LE(p);
    const cap=u32(174)/1000,total=u32(186)/1000,soh=b[190];
    if(cap>=0&&cap<10000)extras.capacity_remaining_ah=+cap.toFixed(3);
    if(total>=0&&total<1e9)extras.total_cycle_capacity_ah=+total.toFixed(3);
    if(soh<=100)extras.soh_pct=soh;
    extras.balance_current_a=+(i16(170)/1000).toFixed(3);
    extras.balance_action=b[172];
    extras.balance_state=b[172]===0?"Arrêt":b[172]===1?"Charge":
      b[172]===2?"Décharge":null;
    extras.total_runtime_h=+(u32(194)/3600).toFixed(2);
    extras.cell_wire_warning_mask="0x"+u32(146).toString(16).padStart(8,"0").toUpperCase();
    extras.precharge=b[200]===1;
    extras.heating=b[215]===1;
    const rawStatus=b[280];
    if(rawStatus<=2)extras.charge_status=["Bulk","Absorption","Float"][rawStatus];
    for(const [k,pos] of [["temp3_c",258],["temp4_c",256],["temp5_c",254]]){
      const value=i16(pos)/10;
      // A raw zero on optional channels 3–5 is ambiguous; do not invent 0°C.
      extras[k]=value!==0&&value>=-80&&value<=160?+(value.toFixed(1)):null;
    }
    for(let i=0;i<Math.min(32,Number(e.cell_count)||0);i++){
      const value=b.readUInt16LE(80+i*2)/1000;
      if(value>0&&value<100)extras["cell_"+String(i+1).padStart(2,"0")+"_resistance_ohm"]=+value.toFixed(3);
    }
  }
 }
 out={kind:"telemetry",address:mac,data:e,extras};
}else if(["disconnected","stream_stale"].includes(e.type)){
 out={kind:"lifecycle",address:mac,event:e.type};
}
if(!out)return null;
msg.method="POST";
msg.url="http://127.0.0.1:1896/mqtt";
msg.headers={
 "Content-Type":"application/json",
 "X-BLE-Bridge-Token":String(env.get("BLE_BRIDGE_TOKEN")||"")
};
msg.payload=JSON.stringify(out);
return msg;

const status=Number(msg.statusCode)||0,now=Date.now();
if(status===202){node.status({fill:"green",shape:"dot",text:"MQTT reçu"});return null;}
const last=context.get("last_failed_mqtt")||0;
if(now-last>=60000){context.set("last_failed_mqtt",now);
 node.warn("MQTT publisher HTTP status "+status+" : "+JSON.stringify(msg.payload||{}).slice(0,150));}
node.status({fill:"red",shape:"ring",text:"MQTT échec "+status});
return null;
